import path from 'node:path'
import { ensureDir, writeJsonFileAtomic } from './fs.js'
import type { HackonConfig, ValidationProfile, TargetConfig } from './config.js'
import type { RuntimePaths } from './runtime-paths.js'
import { getTaskArtifactRoot } from './runtime-paths.js'
import type { CommandExecutor } from './shell.js'
import type { TaskRecord } from './state/model.js'
import { extractIntegrationScenarioIds, isIntegrationScenarioGapTask } from './task-focus.js'

export type ValidationArtifact = {
  taskId: string
  profileId: string
  required: boolean
  command: string[]
  targetResult: {
    exitCode: number
    findings: string[]
  } | null
  worktreeResult: {
    exitCode: number
    findings: string[]
  } | null
  newFindings: string[]
  status: 'passed' | 'failed' | 'skipped' | 'blocked'
  note: string | null
}

export async function runValidationProfiles(
  runtimePaths: RuntimePaths,
  config: HackonConfig,
  _target: TargetConfig,
  task: TaskRecord,
  worktreePath: string,
  canonicalClonePath: string,
  executor: CommandExecutor,
  options: {
    allowApprovalSensitiveProfiles?: boolean
    includeOptionalProfiles?: boolean
  } = {},
): Promise<{ artifacts: ValidationArtifact[]; hasRequiredFailures: boolean; hasBlockingIssues: boolean }> {
  const profiles = resolveProfiles(config, task.validationProfileIds)
  const artifacts: ValidationArtifact[] = []
  const validationsDir = path.join(getTaskArtifactRoot(runtimePaths, task.taskId), 'validation')
  await ensureDir(validationsDir)

  for (const profile of profiles) {
    for (const command of resolveValidationCommands(profile, task)) {
      const executionDecision = resolveExecutionDecision(profile, {
        allowApprovalSensitiveProfiles: options.allowApprovalSensitiveProfiles ?? false,
        includeOptionalProfiles: options.includeOptionalProfiles ?? false,
      })

      if (executionDecision !== 'run') {
        const artifact: ValidationArtifact = {
          taskId: task.taskId,
          profileId: profile.id,
          required: profile.required,
          command,
          targetResult: null,
          worktreeResult: null,
          newFindings: [],
          status: executionDecision,
          note: executionDecision === 'blocked'
            ? 'Approval-sensitive required validation was not explicitly allowed.'
            : profile.autonomyClass === 'optional'
              ? 'Optional validation profile was not requested.'
              : 'Approval-sensitive advisory validation was skipped because it was not explicitly allowed.',
        }
        artifacts.push(artifact)
        await writeJsonFileAtomic(path.join(validationsDir, `${profile.id}-${sanitizeCommand(command)}.json`), artifact)
        continue
      }

      const baseline = profile.baselineProfile === 'target_head'
        ? await runValidationCommand(
          command,
          resolveBaselineCwd(profile.cwdMode, runtimePaths.repoRoot, canonicalClonePath),
          profile.parser,
          executor,
          task,
        )
        : null
      const worktree = await runValidationCommand(
        command,
        resolveWorktreeCwd(profile.cwdMode, runtimePaths.repoRoot, canonicalClonePath, worktreePath),
        profile.parser,
        executor,
        task,
      )

      const newFindings = profile.baselineProfile === 'target_head'
        ? worktree.findings.filter((finding) => !(baseline?.findings.includes(finding) ?? false))
        : worktree.exitCode !== 0
          ? worktree.findings.length > 0 ? worktree.findings : [`exit:${worktree.exitCode}`]
          : []

      const artifact: ValidationArtifact = {
        taskId: task.taskId,
        profileId: profile.id,
        required: profile.required,
        command,
        targetResult: baseline,
        worktreeResult: worktree,
        newFindings,
        status: newFindings.length > 0 ? 'failed' : 'passed',
        note: null,
      }
      artifacts.push(artifact)
      await writeJsonFileAtomic(path.join(validationsDir, `${profile.id}-${sanitizeCommand(command)}.json`), artifact)
    }
  }

  return {
    artifacts,
    hasRequiredFailures: artifacts.some((artifact) => artifact.status === 'failed' && artifact.required),
    hasBlockingIssues: artifacts.some((artifact) => artifact.status === 'blocked'),
  }
}

function resolveProfiles(config: HackonConfig, profileIds: string[]): ValidationProfile[] {
  return profileIds
    .map((profileId) => config.validationProfiles.find((profile) => profile.id === profileId))
    .filter((profile): profile is ValidationProfile => Boolean(profile))
}

function resolveBaselineCwd(cwdMode: ValidationProfile['cwdMode'], repoRoot: string, canonicalClonePath: string): string {
  switch (cwdMode) {
    case 'repo_root':
      return repoRoot
    case 'target_root':
      return canonicalClonePath
    case 'worktree':
      return canonicalClonePath
  }
}

function resolveWorktreeCwd(cwdMode: ValidationProfile['cwdMode'], repoRoot: string, canonicalClonePath: string, worktreePath: string): string {
  switch (cwdMode) {
    case 'repo_root':
      return repoRoot
    case 'target_root':
      return canonicalClonePath
    case 'worktree':
      return worktreePath
  }
}

function resolveExecutionDecision(
  profile: ValidationProfile,
  options: {
    allowApprovalSensitiveProfiles: boolean
    includeOptionalProfiles: boolean
  },
): 'run' | 'skipped' | 'blocked' {
  if (profile.autonomyClass === 'optional' && !options.includeOptionalProfiles) {
    return 'skipped'
  }

  if (profile.autonomyClass === 'approval_sensitive' && !options.allowApprovalSensitiveProfiles) {
    return profile.required ? 'blocked' : 'skipped'
  }

  return 'run'
}

function resolveValidationCommands(profile: ValidationProfile, task: TaskRecord): string[][] {
  if (profile.id === 'integration-tests' && isIntegrationScenarioGapTask(task)) {
    const scenarioIds = extractIntegrationScenarioIds(task)
    if (scenarioIds.length > 0) {
      return scenarioIds.map((scenarioId) => ['yarn', 'mercato', 'test:integration', '--filter', scenarioId])
    }
  }

  return profile.commands
}

async function runValidationCommand(
  command: string[],
  cwd: string,
  parser: ValidationProfile['parser'],
  executor: CommandExecutor,
  task: TaskRecord,
): Promise<{ exitCode: number; findings: string[] }> {
  const result = await executor.run(command[0] ?? '', command.slice(1), {
    cwd,
    timeoutMs: 20 * 60 * 1000,
  })
  return {
    exitCode: result.exitCode,
    findings: normalizeFindings(result.stdout, result.stderr, parser, result.exitCode, task),
  }
}

function normalizeFindings(
  stdout: string,
  stderr: string,
  parser: ValidationProfile['parser'],
  exitCode: number,
  task: TaskRecord,
): string[] {
  if (parser === 'exit_code') {
    return exitCode === 0 ? [] : [`exit:${exitCode}`]
  }

  if (parser === 'integration_spec_coverage') {
    return normalizeIntegrationSpecCoverageFindings(stdout, stderr, exitCode, task)
  }

  const combined = `${stdout}\n${stderr}`
  return [...new Set(combined
    .split('\n')
    .map((line) => line.trim())
    .filter((line) => line.length > 0)
    .slice(-40))]
}

function normalizeIntegrationSpecCoverageFindings(
  stdout: string,
  stderr: string,
  exitCode: number,
  task: TaskRecord,
): string[] {
  const report = parseIntegrationSpecCoverageReport(`${stdout}\n${stderr}`)
  const scenarioIds = extractIntegrationScenarioIds(task)
  if (report) {
    const uncoveredIds = scenarioIds.length > 0
      ? scenarioIds.filter((scenarioId) => report.uncoveredScenarioIds.includes(scenarioId))
      : report.uncoveredScenarioIds
    return uncoveredIds.map((scenarioId) => `uncovered:${scenarioId}`)
  }

  if (exitCode === 0) {
    return []
  }

  const fallbackFindings = `${stdout}\n${stderr}`
    .split('\n')
    .map((line) => line.trim())
    .filter((line) => line.length > 0)
    .slice(-10)

  return fallbackFindings.length > 0 ? fallbackFindings : [`exit:${exitCode}`]
}

function parseIntegrationSpecCoverageReport(output: string): { uncoveredScenarioIds: string[] } | null {
  const firstBrace = output.indexOf('{')
  const lastBrace = output.lastIndexOf('}')
  if (firstBrace === -1 || lastBrace === -1 || lastBrace <= firstBrace) {
    return null
  }

  let parsed: unknown
  try {
    parsed = JSON.parse(output.slice(firstBrace, lastBrace + 1))
  } catch {
    return null
  }

  if (!parsed || typeof parsed !== 'object') {
    return null
  }

  const report = parsed as { uncoveredScenarioIds?: unknown }
  return {
    uncoveredScenarioIds: Array.isArray(report.uncoveredScenarioIds)
      ? report.uncoveredScenarioIds
        .filter((value): value is string => typeof value === 'string' && value.length > 0)
        .map((value) => value.toUpperCase())
      : [],
  }
}

function sanitizeCommand(command: string[]): string {
  return command.join('-').replace(/[^a-z0-9-]+/gi, '_')
}
